import {readSync,writeSync} from 'node:fs';
import {setImmediate} from 'node:timers/promises';
import {PythonSession} from './packages/safe-python/src/index.ts';
import {codecUtf7UserAuditCases,codecUtf7UserAuditServiceSource} from './packages/safe-python/src/codec-utf7-user-audit-cases.ts';
let reads=0,writes=0;
const mode=process.argv[1],controller=new AbortController();
const output={write(text){writes++;writeSync(1,text);},flush(){}};
const input={readLine(){reads++;const data=Buffer.alloc(32);const length=readSync(0,data,0,data.length,null);if(mode.startsWith('abort'))controller.abort();if(mode==='abort-throw')throw Error('service failed after cancellation');return data.subarray(0,length).toString('utf8');}};
let results=[];
for(const source of mode==='corpus'?codecUtf7UserAuditCases.map(row=>row.source):[codecUtf7UserAuditServiceSource]){
 await setImmediate();
 const session=new PythonSession({limits:{maxSteps:3000000,maxAllocatedBytes:32000000,maxDepth:100},hashSeed:[1n,2n],output,input,signal:controller.signal});
 const result=session.exec(source);
 results.push(mode.startsWith('abort')?{result,next:session.eval('1')}:{status:result.status});
}
writeSync(2,JSON.stringify({reads,writes,results}));
